html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro who(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:.1f}".format(value | float) if value else "" }}{%- endmacro -%}
{%- macro person(employee) -%}{{ v(frappe.db.get_value("Employee", employee, "employee_name") if employee else "") }}{%- endmacro -%}
<style>
.lpl-form { font-family: Cambria, Georgia, serif; font-size: 11.5px; color: #000; line-height: 1.45; }
.lpl-form p { margin: 0 0 8px; }
.lpl-form table { width: 100%; border-collapse: collapse; margin: 0 0 12px; }
.lpl-form tr { page-break-inside: avoid; }
.lpl-form th, .lpl-form td { border: 1px solid #000; padding: 4px 6px; vertical-align: top; text-align: left; }
.lpl-form th { background: #f2f2f2; font-weight: bold; }
.lpl-form h3 { font-size: 12.5px; text-align: center; text-transform: uppercase; margin: 8px 0 12px; }
.lpl-form h4 { font-size: 11.5px; font-weight: bold; margin: 12px 0 6px; }
.lpl-form .rule { min-height: 34px; white-space: pre-wrap; border: 1px solid #000; padding: 4px 6px; margin: 0 0 12px; }
.lpl-form .scores td, .lpl-form .scores th { text-align: center; }
.lpl-form .scores td { font-weight: bold; }
.lpl-form .right { text-align: right; }
.lpl-form .muted { color: #444; font-size: 10.5px; }
.lpl-form table.bare { border: none; }
.lpl-form table.bare > tbody > tr > td, .lpl-form table.bare > tr > td { border: none; padding: 0; }
.lpl-form .pre { white-space: pre-wrap; }
.lpl-form .nowrap { white-space: nowrap; }
.lpl-form .grid td, .lpl-form .grid th { text-align: center; vertical-align: middle; height: 30px; }
.lpl-form .grid td { width: 27%; font-size: 10.5px; }
.lpl-form .grid .axis { width: 19%; font-weight: bold; background: #f2f2f2; }
.lpl-form .grid .here { background: #bfbfbf; font-weight: bold; font-size: 11.5px; }
.lpl-form .sign td { border: none; padding: 14px 6px 0 0; width: 33%; }
.lpl-form .sign .line { border-top: 1px solid #000; padding-top: 3px; }
</style>
{%- set sees_boxes = ((doc.candidates | length) > 0) and doc.candidates[0].has_permlevel_access_to("box_name") -%}
{%- set follow = talent_follow_through(doc.name) -%}
{%- set plans = follow.plans or {} -%}
<div class="lpl-form">
<h3>Succession Slate</h3>
<table>
<tr><th style="width:18%">Role</th><td>{{ v(doc.designation) }}</td><th style="width:17%">Department</th><td>{{ v(doc.department) }}</td></tr>
<tr><th>Plant</th><td>{{ v(doc.branch) }}</td><th>Review Year</th><td>{{ doc.review_year or "" }}</td></tr>
<tr><th>Held By</th><td>{{ v(doc.incumbent_name) }}</td><th>Risk if Lost</th><td>{{ v(doc.risk_level) }}</td></tr>
<tr><th>One Person Only</th><td>{{ "Yes" if doc.single_person_role else "No" }}</td>
<th>Known Exit Due</th><td>{{ day(doc.retirement_or_exit_due) }}</td></tr>
<tr><th>Coverage</th><td><b>{{ v(doc.coverage) }}</b></td><th>Status</th><td>{{ v(doc.status) }}</td></tr>
</table>
{%- if doc.criticality_notes %}
<p class="pre"><b>Why the role is critical:</b> {{ v(doc.criticality_notes) }}</p>
{%- endif %}

<table class="scores">
<tr><th>Ready Now</th><th>Ready in 1 to 2 Years</th><th>Emerging</th><th>Bench Depth</th></tr>
<tr><td>{{ doc.ready_now or 0 }}</td><td>{{ doc.ready_soon or 0 }}</td><td>{{ doc.emerging or 0 }}</td>
<td>{{ doc.bench_depth or 0 }}</td></tr>
</table>

<h4>Successors, Readiest First</h4>
{%- set ns = namespace(n=0) %}
<table>
<tr><th style="width:4%">#</th><th style="width:18%">Successor</th><th style="width:15%">Current Role</th>
<th style="width:12%">Readiness</th>{% if sees_boxes %}<th style="width:12%">Box</th>{% endif %}
<th>Development Needs</th><th style="width:17%">Development Plan</th></tr>
{%- for level in ["Ready Now", "Ready in 1-2 Years", "Emerging", "Gap"] %}
{%- for row in doc.candidates if row.readiness == level %}
{%- set ns.n = ns.n + 1 %}
{%- set progress = plans.get(row.development_plan) if row.development_plan else None %}
<tr><td>{{ ns.n }}</td><td>{{ v(row.employee_name or row.employee) }}</td><td>{{ v(row.candidate_designation) }}</td>
<td>{{ v(row.readiness) }}</td>{% if sees_boxes %}<td>{{ v(row.box_name) }}</td>{% endif %}
<td class="pre">{{ v(row.development_needs) }}</td>
<td>{{ v(row.development_plan) }}{% if progress and progress.actions %}<br><span class="muted">{{ progress.done }} of {{ progress.actions }} actions done</span>{% endif %}</td></tr>
{%- endfor %}
{%- endfor %}
{%- if not ns.n %}
<tr><td colspan="{{ 7 if sees_boxes else 6 }}">No successor is named.</td></tr>
{%- endif %}
</table>
{%- if doc.gap and doc.gap_notes %}
<p class="pre"><b>Council's note on the gap:</b> {{ v(doc.gap_notes) }}</p>
{%- endif %}

{%- set opening = (follow.opening or {}).get("name") or doc.job_opening %}
{%- if follow.exit or follow.promotion or follow.requisition or opening or doc.previous_incumbent %}
<h4>Filling the Role</h4>
<table>
{%- if follow.exit %}
<tr><th style="width:22%">Holder's Exit</th><td>{{ v(follow.exit.custom_reason) }}, last day {{ day(follow.exit.custom_relieving_date) }}
 ({{ v(follow.exit.name) }})</td></tr>
{%- endif %}
{%- if follow.promotion %}
<tr><th style="width:22%">Promotion</th><td>{{ v(follow.promotion.employee_name) }}, from {{ day(follow.promotion.effective_date) }}
 ({{ v(follow.promotion.name) }}{% if follow.promotion.status %}, {{ v(follow.promotion.status) }}{% endif %})</td></tr>
{%- endif %}
{%- if follow.requisition %}
<tr><th style="width:22%">Replacement</th><td>Job requisition {{ v(follow.requisition.name) }}
 ({{ v(follow.requisition.workflow_state or follow.requisition.status) }})</td></tr>
{%- endif %}
{%- if opening %}
<tr><th style="width:22%">Recruiting</th><td>Job opening {{ v(opening) }}</td></tr>
{%- endif %}
{%- if doc.previous_incumbent %}
<tr><th style="width:22%">Handed Over</th><td>From {{ v(doc.previous_incumbent_name) }} to {{ v(doc.incumbent_name) }}
 on {{ day(doc.handed_over_on) }}</td></tr>
{%- endif %}
</table>
{%- endif %}

<table class="sign"><tr>
<td><div class="line">Nominated by: {{ who(doc.nominated_by) }}</div><span class="muted">Date {{ day(doc.nominated_on) }}</span></td>
<td><div class="line">Confirmed by the Talent Council: {{ who(doc.confirmed_by) }}</div><span class="muted">Date {{ day(doc.confirmed_on) }}</span></td>
<td><div class="line">Human Resources Manager</div><span class="muted">Sign and date</span></td>
</tr></table>
</div>
